CREATE TABLE retired_tenant_keys (id TEXT PRIMARY KEY NOT NULL);
INSERT INTO retired_tenant_keys SELECT DISTINCT json_extract(g.value,'$.subjectId') FROM model_workspace w,json_each(w.reference_json,'$.grants') g WHERE json_extract(g.value,'$.subjectType')='key' AND json_type(g.value,'$.subjectId')='text' AND NOT EXISTS (SELECT 1 FROM json_each(w.reference_json,'$.apiKeys') k WHERE json_extract(k.value,'$.id')=json_extract(g.value,'$.subjectId'));
CREATE TABLE market_monthly_charges (period TEXT NOT NULL,tenant_id TEXT NOT NULL,amount_micros INTEGER NOT NULL CHECK(amount_micros>=0),PRIMARY KEY(period,tenant_id));
CREATE TABLE market_charge_receipts (tenant_id TEXT NOT NULL,request_id TEXT NOT NULL,period TEXT NOT NULL,PRIMARY KEY(tenant_id,request_id));
CREATE INDEX market_charge_receipts_period ON market_charge_receipts(period);
INSERT INTO market_monthly_charges SELECT strftime('%Y-%m',c.created_at/1000,'unixepoch','+8 hours'),c.tenant_id,SUM(json_extract(s.payload_json,'$.saleTrial.amount')) FROM market_calls c JOIN simulation_records s ON s.kind='usage' AND s.id=c.usage_id WHERE json_extract(s.payload_json,'$.billingStatus')='billable' AND json_extract(s.payload_json,'$.saleTrial.currency')='CNY' AND json_type(s.payload_json,'$.saleTrial.amount')='integer' AND json_extract(s.payload_json,'$.saleTrial.amount')>=0 GROUP BY 1,2;
INSERT INTO market_charge_receipts SELECT c.tenant_id,c.request_id,strftime('%Y-%m',c.created_at/1000,'unixepoch','+8 hours') FROM market_calls c JOIN simulation_records s ON s.kind='usage' AND s.id=c.usage_id WHERE json_extract(s.payload_json,'$.billingStatus')='billable' AND json_extract(s.payload_json,'$.saleTrial.currency')='CNY' AND json_type(s.payload_json,'$.saleTrial.amount')='integer' AND json_extract(s.payload_json,'$.saleTrial.amount')>=0 AND strftime('%Y-%m',c.created_at/1000,'unixepoch','+8 hours')=strftime('%Y-%m','now','+8 hours');
UPDATE db_state SET schema_version=13 WHERE id=1;
